observation.command:
echo "=== Password hashes for super admin (id 1) and club-admin-1 (id 2) ==="
docker exec vereinfacht-database-1 mariadb -uverein -pverein verein -N -e "SELECT id,email,password FROM users WHERE id IN (1,2);" 2>/dev/null
echo
echo "=== Verify 'password' matches via PHP password_verify ==="
docker exec vereinfacht-tooling-1 php -r '
$hashes = [
  "user1(super admin)" => trim(shell_exec("docker exec vereinfacht-database-1 mariadb -uverein -pverein verein -N -e \"SELECT password FROM users WHERE id=1;\" 2>/dev/null")),
  "user2(club-admin-1)" => trim(shell_exec("docker exec vereinfacht-database-1 mariadb -uverein -pverein verein -N -e \"SELECT password FROM users WHERE id=2;\" 2>/dev/null")),
];
foreach ($hashes as $label => $hash) {
  $ok = password_verify("password", $hash) ? "VALID" : "invalid";
  echo "$label => $ok\n";
}
' 2>&1 | grep -v Deprecated
